<?= $this->extend('layout') ?><?= $this->section('content') ?><div class="card"><h1>Rekap Nilai: <?= esc($exam['title']) ?></h1><a class="btn" href="/guru/results/<?= (int)$exam['id'] ?>/csv">Ekspor CSV</a><table><tr><th>Peserta</th><th>Status</th><th>Mulai</th><th>Kumpul</th><th>Nilai objektif</th><th>Esai</th></tr><?php foreach($attempts as $a): ?><tr><td><?= esc($a['full_name']) ?><br><?= esc($a['username']) ?></td><td><?= esc($a['status']) ?></td><td><?= esc($a['started_at']) ?></td><td><?= esc($a['submitted_at']??'—') ?></td><td><?= esc($a['objective_score']??'—') ?></td><td><?= $a['essay_pending']?'Perlu ditinjau':'—' ?></td></tr><?php endforeach ?></table></div>
